'use client';
import{jsx as _jsx}from"react/jsx-runtime";
import{useEffect,useMemo,useRef,useState}from'react';
import{useSpring}from'../../react/index.js';
const clamp01=(n)=>(Number.isFinite(n)?Math.min(1,Math.max(0,n)):0);
const FLOOR_DB=60;
export function rmsLevel(samples){
const n=samples.length;
if(!n)
return 0;
let sum=0;
for(let i=0;i<n;i+=1){
const s=samples[i];
if(Number.isFinite(s))
sum+=s*s;
}
const rms=Math.sqrt(sum/n);
if(rms<=0)
return 0;
return clamp01((20*Math.log10(rms)+FLOOR_DB)/FLOOR_DB);
}
export function levelBars(level,count){
const n=Number.isFinite(count)?Math.max(0,Math.floor(count)):0;
const l=clamp01(level);
const mid=(n-1)/2;
return Array.from({length:n},(_,i)=>{
const dist=mid>0?Math.abs(i-mid)/mid:0;
return Math.min(1,Math.max(0.1,0.1+0.9*l*(1-0.5*dist)));
});
}
export function AudioLevelMeter({level,stream,bars=5,label='Microphone level'}){
const count=Number.isFinite(bars)?Math.min(32,Math.max(1,Math.floor(bars))):5;
const[heard,setHeard]=useState(0);
const controlled=level!==undefined;
const target=clamp01(controlled?level:heard);
const root=useRef(null);
const shown=useRef(target);
const seed=useMemo(()=>levelBars(target,count),[count]);
const paint=(value)=>{
shown.current=value;
const el=root.current;
if(!el)
return;
el.style.setProperty('--cieo-level',value.toFixed(3));
const heights=levelBars(value,count);
for(let i=0;i<el.children.length;i+=1)
el.children[i].style.setProperty('--cieo-bar',heights[i].toFixed(3));
};
useSpring(target,paint,{preset:'base'});
useEffect(()=>paint(shown.current),[count]);
useEffect(()=>{
if(!stream||controlled)
return;
const Ctor=window.AudioContext??window.webkitAudioContext;
if(!Ctor)
return;
let ctx;
try{
ctx=new Ctor();
}
catch{
return;
}
const source=ctx.createMediaStreamSource(stream);
const analyser=ctx.createAnalyser();
analyser.fftSize=1024;
source.connect(analyser);
void ctx.resume?.().catch(()=>{});
const buffer=new Float32Array(analyser.fftSize);
let raf=0;
let lastAt=0;
let last=0;
const loop=(t)=>{
raf=requestAnimationFrame(loop);
if(t-lastAt<50)
return;
lastAt=t;
analyser.getFloatTimeDomainData(buffer);
const next=Math.round(rmsLevel(buffer)*50)/50;
if(next!==last){
last=next;
setHeard(next);
}
};
raf=requestAnimationFrame(loop);
return()=>{
cancelAnimationFrame(raf);
try{
source.disconnect();
}
catch{
}
void ctx.close().catch(()=>{});
setHeard(0);
};
},[stream,controlled]);
return(_jsx("span",{ref:root,role:"img","aria-label":label,className:"cieo cieo-audio-level-meter",style:{'--cieo-level':target.toFixed(3)},children:seed.map((h,i)=>(_jsx("span",{"aria-hidden":"true",className:"cieo-audio-level-meter-bar",style:{'--cieo-bar':h.toFixed(3)}},i)))}));
}
